DROP TABLE IF EXISTS `accounting_accounts`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `accounting_accounts` (
  `id` bigint unsigned NOT NULL,
  `name` varchar(250) COLLATE utf8mb3_unicode_ci NOT NULL,
  `is_class` tinyint(1) DEFAULT NULL,
  `is_group` tinyint(1) DEFAULT NULL,
  `is_account` tinyint(1) DEFAULT NULL,
  `is_subaccount` tinyint(1) DEFAULT NULL,
  `is_auxiliary` tinyint(1) DEFAULT NULL,
  `is_subauxiliary` tinyint(1) DEFAULT NULL,
  `niif` tinyint(1) NOT NULL DEFAULT '1',
  `cash_flow` tinyint(1) DEFAULT NULL,
  `exogenous` tinyint(1) DEFAULT NULL,
  `base_value` tinyint(1) DEFAULT NULL,
  `nature` varchar(1) COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `term` tinyint(1) DEFAULT NULL,
  `favorite` tinyint(1) DEFAULT NULL,
  `status` tinyint(1) NOT NULL DEFAULT '1',
  `deleted_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  UNIQUE KEY `accounting_accounts_id_unique` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_unicode_ci;
