--
-- Table structure for table `contact_statements`
--

DROP TABLE IF EXISTS `contact_statements`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `contact_statements` (
  `contact_id` int unsigned NOT NULL,
  `advance` double(16,2) NOT NULL DEFAULT '0.00' COMMENT 'Anticipos',
  `credit_balance` double(16,2) NOT NULL DEFAULT '0.00' COMMENT 'Saldo a Favor',
  `invoices_total` double(16,2) NOT NULL DEFAULT '0.00' COMMENT 'Módulo Facturación',
  `debit_notes_total` double(16,2) NOT NULL DEFAULT '0.00' COMMENT 'Módulo Facturación',
  `debit_notes_counter` int unsigned NOT NULL DEFAULT '0' COMMENT 'Módulo Facturación',
  `debit_notes_extra` json DEFAULT NULL COMMENT 'Módulo Facturación',
  `invoices_counter` int unsigned NOT NULL DEFAULT '0' COMMENT 'Módulo Facturación',
  `invoices_extra` json DEFAULT NULL COMMENT 'Módulo Facturación',
  `credit_notes_total` double(16,2) NOT NULL DEFAULT '0.00' COMMENT 'Módulo Facturación',
  `credit_notes_counter` int unsigned NOT NULL DEFAULT '0' COMMENT 'Módulo Facturación',
  `credit_notes_extra` json DEFAULT NULL COMMENT 'Módulo Facturación',
  `payments_received_total` double(16,2) NOT NULL DEFAULT '0.00' COMMENT 'Módulo Facturación',
  `payments_received_counter` int unsigned NOT NULL DEFAULT '0' COMMENT 'Módulo Facturación',
  `payments_received_extra` json DEFAULT NULL COMMENT 'Módulo Facturación',
  `estimates_extra` json DEFAULT NULL COMMENT 'Módulo Facturación',
  `remissions_extra` json DEFAULT NULL COMMENT 'Módulo Facturación',
  `billing_retentions_total` double(16,2) NOT NULL DEFAULT '0.00' COMMENT 'Módulo Facturación',
  `invoices_migration_total` double(16,2) NOT NULL DEFAULT '0.00' COMMENT 'Módulo Facturación',
  `bills_total` double(16,2) NOT NULL DEFAULT '0.00' COMMENT 'Módulo Gastos',
  `bills_counter` int unsigned NOT NULL DEFAULT '0' COMMENT 'Módulo Gastos',
  `bills_extra` json DEFAULT NULL COMMENT 'Módulo Gastos',
  `payments_total` double(16,2) NOT NULL DEFAULT '0.00' COMMENT 'Módulo Gastos',
  `payments_counter` int unsigned NOT NULL DEFAULT '0' COMMENT 'Módulo Gastos',
  `payments_extra` json DEFAULT NULL COMMENT 'Módulo Gastos',
  `purchase_orders_extra` json DEFAULT NULL COMMENT 'Módulo Gastos',
  `expense_retentions_total` double(16,2) NOT NULL DEFAULT '0.00' COMMENT 'Módulo Gastos',
  `bills_migration_total` double(16,2) NOT NULL DEFAULT '0.00' COMMENT 'Módulo Gastos',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`contact_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

