DROP TABLE IF EXISTS `contacts`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `contacts` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `lead` tinyint(1) NOT NULL DEFAULT '0',
  `client` tinyint(1) NOT NULL DEFAULT '0',
  `provider` tinyint(1) NOT NULL DEFAULT '0',
  `is_own_tenant_provider` tinyint(1) NOT NULL DEFAULT '0',
  `group` tinyint(1) NOT NULL DEFAULT '0',
  `register_type` smallint unsigned NOT NULL,
  `identity_document_type_id` varchar(255) COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `document_number` varchar(255) COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `check_digit` char(255) COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `person_type_id` smallint unsigned DEFAULT NULL,
  `gender_id` smallint unsigned NOT NULL DEFAULT '0',
  `national` tinyint(1) NOT NULL DEFAULT '1',
  `names` varchar(255) COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `surnames` varchar(255) COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `business_name` varchar(255) COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `tradename` varchar(255) COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `full_name` varchar(255) COLLATE utf8mb3_unicode_ci NOT NULL,
  `email` varchar(255) COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `contributory_scheme_id` smallint unsigned DEFAULT NULL,
  `iva_responsible` tinyint(1) NOT NULL DEFAULT '0',
  `country` json DEFAULT NULL,
  `region` json DEFAULT NULL,
  `city` json DEFAULT NULL,
  `neighborhood` varchar(255) COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `address` varchar(255) COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `address_complement` varchar(255) COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `shipping_address` json DEFAULT NULL,
  `dial_code` varchar(255) COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `phone` varchar(255) COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `extension` varchar(255) COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `mobile` varchar(255) COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `main_contact` json DEFAULT NULL,
  `photo` varchar(500) COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `payment_condition_id` smallint unsigned DEFAULT NULL,
  `economic_activity` json DEFAULT NULL,
  `tax_responsibility_id` varchar(255) COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `obligations` json DEFAULT NULL,
  `zip_code` varchar(255) COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `notes` varchar(255) COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `price_list_id` int unsigned DEFAULT NULL,
  `max_billing_value` double(16,2) DEFAULT NULL,
  `e_user` tinyint(1) NOT NULL DEFAULT '0',
  `e_status` tinyint(1) NOT NULL DEFAULT '0',
  `from_ecommerce` tinyint(1) NOT NULL DEFAULT '0',
  `e_register_source` varchar(255) COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `tenant_id` int unsigned DEFAULT NULL,
  `headquarter_id` int unsigned DEFAULT NULL,
  `external_id` json DEFAULT NULL,
  `status` tinyint(1) NOT NULL DEFAULT '1',
  `user_id` int unsigned NOT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `contacts_payment_condition_id_foreign` (`payment_condition_id`),
  KEY `contacts_price_list_id_foreign` (`price_list_id`),
  KEY `contacts_headquarter_id_foreign` (`headquarter_id`),
  CONSTRAINT `contacts_headquarter_id_foreign` FOREIGN KEY (`headquarter_id`) REFERENCES `headquarters` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `contacts_payment_condition_id_foreign` FOREIGN KEY (`payment_condition_id`) REFERENCES `payment_conditions` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `contacts_price_list_id_foreign` FOREIGN KEY (`price_list_id`) REFERENCES `price_lists` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=261 DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_unicode_ci;
