DROP TABLE IF EXISTS `employee_contracts`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `employee_contracts` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `employee_id` int unsigned NOT NULL,
  `employee_type` json NOT NULL,
  `employee_subtype` json NOT NULL,
  `high_penson_risk` tinyint(1) NOT NULL DEFAULT '0',
  `integral_salary` tinyint(1) NOT NULL DEFAULT '0',
  `type` json NOT NULL,
  `start_date` date NOT NULL,
  `end_date` date DEFAULT NULL,
  `salary` double(16,2) NOT NULL,
  `transport_subsidy` tinyint(1) NOT NULL DEFAULT '0',
  `risk_type` json NOT NULL,
  `holidays_enjoyed` smallint unsigned NOT NULL,
  `health_provider_id` bigint unsigned DEFAULT NULL,
  `health_provider` json DEFAULT NULL,
  `pension_provider` json DEFAULT NULL,
  `pension_provider_id` bigint unsigned DEFAULT NULL,
  `severance_provider` json DEFAULT NULL,
  `severance_provider_id` bigint unsigned DEFAULT NULL,
  `family_compensation_fund_provider` json DEFAULT NULL,
  `family_compensation_fund_provider_id` bigint unsigned DEFAULT NULL,
  `settlement_cause` varchar(255) COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `settlement_with_just_cause` tinyint(1) NOT NULL DEFAULT '1',
  `settlement_probationary_period` tinyint(1) NOT NULL DEFAULT '0',
  `settlement_date` date DEFAULT NULL,
  `settlement_worked_days` smallint unsigned DEFAULT NULL,
  `settlement_severance_base_days` smallint unsigned NOT NULL DEFAULT '0',
  `settlement_service_bonus_base_days` smallint unsigned NOT NULL DEFAULT '0',
  `settlement_holidays_to_pay` double(19,16) DEFAULT NULL,
  `settlement_salary_base` double(16,2) DEFAULT NULL,
  `settlement_holidays_base` double(16,2) DEFAULT NULL,
  `settlement_severance_base` double(16,2) DEFAULT NULL,
  `settlement_service_bonus_base` double(16,2) DEFAULT NULL,
  `settlement_non_salary_income` double(16,2) DEFAULT NULL,
  `settlement_loans` double(16,2) DEFAULT NULL,
  `settlement_deductions` double(16,2) DEFAULT NULL,
  `settlement_holidays` double(16,2) DEFAULT NULL,
  `settlement_severance` double(16,2) DEFAULT NULL,
  `settlement_severance_interests` double(16,2) DEFAULT NULL,
  `settlement_service_bonus` double(16,2) DEFAULT NULL,
  `settlement_redundancy_payment` double(16,2) DEFAULT NULL,
  `settlement_others` double(16,2) DEFAULT NULL,
  `settlement_total` double(16,2) DEFAULT NULL,
  `settlement_notes` varchar(500) COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `files` json DEFAULT NULL,
  `status` tinyint(1) NOT NULL DEFAULT '1',
  `user_id` int unsigned NOT NULL,
  `settlement_approval_user_id` int unsigned DEFAULT NULL,
  `settlement_approved_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `employee_contracts_employee_id_foreign` (`employee_id`),
  KEY `employee_contracts_health_provider_id_foreign` (`health_provider_id`),
  KEY `employee_contracts_pension_provider_id_foreign` (`pension_provider_id`),
