DROP TABLE IF EXISTS `epayco_payments`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `epayco_payments` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `e_purchase_order` char(36) COLLATE utf8mb3_unicode_ci NOT NULL,
  `ref_payco` bigint unsigned NOT NULL,
  `ref_cliente` varchar(255) COLLATE utf8mb3_unicode_ci NOT NULL,
  `payment` json NOT NULL,
  `date_created` timestamp NOT NULL,
  `date_approved` timestamp NULL DEFAULT NULL,
  `response_code` int NOT NULL,
  `cc_network_response` json DEFAULT NULL,
  `payment_method` varchar(255) COLLATE utf8mb3_unicode_ci NOT NULL,
  `status` varchar(255) COLLATE utf8mb3_unicode_ci NOT NULL,
  `response` varchar(255) COLLATE utf8mb3_unicode_ci NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `epayco_payments_e_purchase_order_foreign` (`e_purchase_order`),
  CONSTRAINT `epayco_payments_e_purchase_order_foreign` FOREIGN KEY (`e_purchase_order`) REFERENCES `ecommerce_purchase_orders` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_unicode_ci;
