--
-- Table structure for table `items`
--

DROP TABLE IF EXISTS `items`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `items` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `uuid` char(36) COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `code` varchar(255) COLLATE utf8mb3_unicode_ci NOT NULL,
  `name` varchar(255) COLLATE utf8mb3_unicode_ci NOT NULL,
  `subname` varchar(255) COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `e_base_offer_price` double DEFAULT NULL,
  `reference` varchar(255) COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `summary` varchar(150) COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `tax_id` smallint unsigned NOT NULL,
  `inventoriable` tinyint(1) NOT NULL,
  `apply_tax_free_days` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Campo para indicar si el producto es excento de IVA para los días que define el gobierno',
  `measurement_unit_id` varchar(255) COLLATE utf8mb3_unicode_ci NOT NULL,
  `category_id` int unsigned NOT NULL,
  `subcategory_id` int unsigned NOT NULL,
  `description` varchar(5000) COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `capacity_amount` double(16,2) DEFAULT NULL,
  `added_sugar` double(16,2) DEFAULT NULL,
  `images` json DEFAULT NULL,
  `supply_rule` tinyint(1) NOT NULL DEFAULT '0',
  `minimun_stock` double(16,5) DEFAULT NULL,
  `supply_quantity` double(16,5) DEFAULT NULL,
  `related_items` json DEFAULT NULL,
  `additional_info_files` json DEFAULT NULL,
  `item_properties` json DEFAULT NULL,
  `is_package` tinyint(1) NOT NULL DEFAULT '0',
  `package_container` json DEFAULT NULL,
  `is_ecommerce` tinyint(1) NOT NULL DEFAULT '0',
  `is_featured` tinyint(1) NOT NULL DEFAULT '0',
  `multiple_payment_providers` tinyint(1) NOT NULL DEFAULT '0',
  `is_subscription` tinyint(1) NOT NULL DEFAULT '0',
  `subscription_frequency` int unsigned NOT NULL DEFAULT '0',
  `e_item_type` tinyint unsigned NOT NULL DEFAULT '1',
  `e_user_purchase_limit` int unsigned NOT NULL DEFAULT '0',
  `e_delivery_conditions` json DEFAULT NULL COMMENT 'Para productos físicos(1) que requieren envío',
  `e_download_files_paths` json DEFAULT NULL COMMENT 'Para productos descargables(2)',
  `e_download_conditions` json DEFAULT NULL COMMENT 'Para productos descargables(2)',
  `e_rating` json DEFAULT NULL,
  `e_rating_average` double(5,2) NOT NULL DEFAULT '0.00',
  `e_home_order` int unsigned DEFAULT NULL,
  `e_is_variation` tinyint(1) NOT NULL DEFAULT '0',
  `e_variations` json DEFAULT NULL,
  `e_variation_parent_id` int unsigned NOT NULL DEFAULT '0',
  `e_sales_counter` double(16,5) NOT NULL DEFAULT '0.00000',
  `e_visible_ecommerce` tinyint(1) NOT NULL DEFAULT '0',
  `e_visible_in_hidden_page` tinyint(1) NOT NULL DEFAULT '0',
  `erp_plan` tinyint(1) NOT NULL DEFAULT '0',
  `erp_package` tinyint(1) NOT NULL DEFAULT '0',
  `e_plan` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Indica si es un plan del Ecommerce',
  `e_package` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Indica si es un paquete del Ecommerce',
  `e_purchase_condition` json DEFAULT NULL,
  `p_plan` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Indica si es un plan de Nómina',
  `p_package` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Indica si es un paquete de Nómina',
  `r_plan` tinyint(1) NOT NULL DEFAULT '0',
  `r_package` tinyint(1) NOT NULL DEFAULT '0',
  `free_layer` tinyint(1) NOT NULL DEFAULT '0',
  `public_plan` tinyint(1) NOT NULL DEFAULT '0',
  `headquarter_id` int unsigned DEFAULT NULL,
  `inventory_group_id` bigint unsigned DEFAULT NULL,
  `is_service` tinyint(1) DEFAULT NULL,
  `external_id` json DEFAULT NULL,
  `status` tinyint(1) NOT NULL DEFAULT '1',
  `user_id` int unsigned NOT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `fixed_sales_value` tinyint(1) NOT NULL DEFAULT '1',
  PRIMARY KEY (`id`),
  UNIQUE KEY `items_code_unique` (`code`),
  KEY `items_category_id_foreign` (`category_id`),
  KEY `items_subcategory_id_foreign` (`subcategory_id`),
  KEY `items_tax_id_foreign` (`tax_id`),
  KEY `items_headquarter_id_foreign` (`headquarter_id`),
  KEY `items_inventory_group_id_foreign` (`inventory_group_id`),
  CONSTRAINT `items_category_id_foreign` FOREIGN KEY (`category_id`) REFERENCES `item_categories` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `items_headquarter_id_foreign` FOREIGN KEY (`headquarter_id`) REFERENCES `headquarters` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
