--
-- Table structure for table `paynilo`
--

DROP TABLE IF EXISTS `paynilo`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `paynilo` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `item` json NOT NULL,
  `payment_link` varchar(255) COLLATE utf8mb3_unicode_ci NOT NULL,
  `paynilo_request` json DEFAULT NULL,
  `payment_status` tinyint unsigned NOT NULL,
  `invoice_sent` tinyint(1) NOT NULL DEFAULT '0',
  `invoice` varchar(255) COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `user_id` int unsigned NOT NULL,
  `is_subscription` tinyint(1) NOT NULL DEFAULT '0',
  `is_subscription_confirmed` tinyint(1) NOT NULL DEFAULT '0',
  `subscription_status` tinyint(1) NOT NULL DEFAULT '0',
