--
-- Table structure for table `paynilo_payments`
--

DROP TABLE IF EXISTS `paynilo_payments`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `paynilo_payments` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `paynilo_id` int unsigned NOT NULL,
  `payment_provider` varchar(50) COLLATE utf8mb3_unicode_ci NOT NULL,
  `payment_id` varchar(50) COLLATE utf8mb3_unicode_ci NOT NULL,
  `status` varchar(25) COLLATE utf8mb3_unicode_ci NOT NULL,
  `paynilo_response` json NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
