--
-- Table structure for table `payrolls`
--

DROP TABLE IF EXISTS `payrolls`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `payrolls` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `start_date` date NOT NULL,
  `end_date` date NOT NULL,
  `frequency` json NOT NULL,
  `total_payment` double(16,2) NOT NULL,
  `total_cost` double(16,2) NOT NULL,
  `service_bonus_period` varchar(25) COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `service_bonus_payment` double(16,2) NOT NULL DEFAULT '0.00',
  `severance_interests_period` varchar(25) COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `severance_interests_payment` double(16,2) NOT NULL DEFAULT '0.00',
  `severance_interests_real_payment` tinyint(1) NOT NULL DEFAULT '0',
  `severance_period` varchar(25) COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `severance_payment` double(16,2) NOT NULL DEFAULT '0.00',
  `settlement_status` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'true: Liquidada | false: Sin liquidar',
  `settled_at` timestamp NULL DEFAULT NULL,
  `payment_status` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '0: Sin pagar | 1: Pagada | 2: Pagada parcialmente',
  `paid_at` timestamp NULL DEFAULT NULL,
  `social_security_payment_status` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '0: Sin pagar | 1: Pagada | 2: Pagada parcialmente',
  `social_security_paid_at` timestamp NULL DEFAULT NULL,
  `DIAN_status` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '0: Sin enviar | 1: Enviada | 2: Enviada parcialmente | 3: Enviada con errores',
  `DIAN_completed_at` timestamp NULL DEFAULT NULL,
  `active` tinyint(1) NOT NULL DEFAULT '0',
  `user_id` int unsigned NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=136 DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

